<script module lang="ts">
/**
 * DateRangePicker.RangeCalendar: the popup's month grid, Calendar's anatomy with the range's cells, on Zag's date-picker machine in range mode.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import * as zag from '@zag-js/date-picker'
import { useMachine } from '@zag-js/svelte'

import {
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import Button from './Button.svelte'
import type { CalendarDate, CalendarMessages } from './Calendar.svelte'
import type { DateRange } from './DateRangePicker.svelte'

export interface DateRangePickerRangeCalendarProps {
  /**
   * The committed range, which the grid starts from.
   */
  value: DateRange | null
  minValue?: CalendarDate
  maxValue?: CalendarDate
  isDateUnavailable?: (date: CalendarDate) => boolean
  locale?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  disabled: boolean
  messages: CalendarMessages
  /**
   * The grid's name, before the month on screen.
   */
  label: string
  onCommit?: (range: DateRange) => void
  onAnchorChange?: (anchored: boolean) => void
}
</script>

<script lang="ts">
let {
  value,
  minValue,
  maxValue,
  isDateUnavailable,
  locale,
  firstDayOfWeek,
  disabled,
  messages,
  label: labelOwn,
  onCommit,
  onAnchorChange,
}: DateRangePickerRangeCalendarProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let travel = $state('next')
let shownMonth = $state('')
let restoring = $state(false)
const language = $derived(locale ?? 'en-US')
const english = $derived(language.toLowerCase().startsWith('en'))
const zone = $derived(Intl.DateTimeFormat().resolvedOptions().timeZone)
const dayName = $derived((date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
  if (!english) return text
  const said = today
    ? selected
      ? `Today, ${text} selected`
      : `Today, ${text}`
    : selected
      ? `${text} selected`
      : text
  if (minValue !== undefined && date.compare(minValue) === 0) return `${said}, First available date`
  if (maxValue !== undefined && date.compare(maxValue) === 0) return `${said}, Last available date`
  return said
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      inline: true,
      selectionMode: 'range' as const,
      locale: language,
      timeZone: zone,
      defaultValue: value === null ? undefined : [value.start, value.end],
      min: minValue,
      max: maxValue,
      startOfWeek: firstDayOfWeek,
      disabled: disabled,
      isDateUnavailable:
        isDateUnavailable === undefined
          ? undefined
          : (date) => isDateUnavailable?.(date as zag.CalendarDate) === true,
      onValueChange: (details) => {
        restoring
          ? (restoring = false)
          : details.value.length === 2 &&
            onCommit?.({
              start: details.value[0] as zag.CalendarDate,
              end: details.value[1] as zag.CalendarDate,
            })
      },
      onVisibleRangeChange: (details) => {
        ;((travel =
          shownMonth !== '' && details.visibleRange.start.toString() < shownMonth
            ? 'previous'
            : 'next'),
          (shownMonth = details.visibleRange.start.toString()))
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const title = $derived(api.visibleRangeText.start)
const named = $derived([label, title].filter(Boolean).join(', '))
const previewing = $derived(
  api.value.length === 1 &&
    api.weeks.some((week) =>
      week.some((date) => api.getDayTableCellState({ value: date }).inHoveredRange),
    ),
)
const dayOf = $derived((date: zag.DateValue) => {
  const cell = api.getDayTableCellState({ value: date })
  const off = disabled || cell.invalid
  const refused = isDateUnavailable?.(date as zag.CalendarDate) === true
  const start = previewing ? cell.firstInHoveredRange : cell.firstInRange
  const end = previewing
    ? cell.lastInHoveredRange
    : api.value.length === 1
      ? cell.firstInRange
      : cell.lastInRange
  const inside = (previewing ? cell.inHoveredRange : cell.inRange) || start || end
  return {
    date,
    cell,
    off,
    unavailable: refused,
    outside: cell.outsideRange,
    selectable: !off && !refused,
    inside,
    start,
    end,
    middle: inside && !start && !end,
    name: dayName(date, cell.valueText, cell.today, inside),
  }
})
const weeks = $derived(api.weeks.map((week) => week.map((date) => dayOf(date))))
const cancel = $derived((): void => {
  if (api.value.length !== 1) return
  const at = api.focusedValue
  restoring = true
  if (value === null) api.clearValue({ focus: false })
  else api.setValue([value.start, value.end])
  api.setFocusedValue(at)
})
const effect1 = () => {
  shownMonth = api.visibleRange.start.toString()
}
watchEffect(effect1)
const effect2 = () => {
  onAnchorChange?.(api.value.length === 1)
}
watchEffect(effect2, { watch: () => api.value.length })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    {...attributes(api.getContentProps())}
    class={styles.root}
    hidden={undefined}
    tabindex={(undefined) as never}
    data-state={undefined}
    role="application"
    aria-label={named}
    ><div class={styles.header}
      ><Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="previous"
        label={messages.previousMonth}
        disabled={disabled || api.getPrevTriggerProps().disabled === true}
        onClick={() => { api.goToPrev() }}
      /><span class={styles.title} aria-live="polite">{title}</span
      ><Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="next"
        label={messages.nextMonth}
        disabled={disabled || api.getNextTriggerProps().disabled === true}
        onClick={() => { api.goToNext() }}
    /></div
    >{#key api.visibleRange.start.toString()
      }<table
        {...attributes(mergeParts(api.getTableProps(), { onKeydown: (event: KeyboardEvent) => { if (event.key === 'Escape') cancel() } }))}
        class={styles.grid}
        tabindex={(undefined) as never}
        aria-label={named}
        data-travel={travel}
        ><thead aria-hidden="true"
          ><tr
            >{#each api.weekDays as weekday (weekday.long)
              }<th scope="col" aria-label={weekday.long}
                ><span aria-hidden="true">{weekday.short}</span
              ></th
            >{/each
          }</tr
        ></thead
        ><tbody
          >{#each weeks as week, at (at)
            }<tr
              >{#each week as day (day.date.toString())
                }{#if day.outside
                  }<td></td
                >{:else
                  }<td
                    class={styles.cell}
                    role="gridcell"
                    aria-disabled={(!day.selectable) ? 'true' : undefined}
                    aria-selected={(day.inside) ? 'true' : undefined}
                    ><div
                      {...attributes(mergeParts(api.getDayTableCellTriggerProps({ value: day.date }), { onFocus: () => { api.setFocusedValue(day.date) }, onKeydown: (event: KeyboardEvent) => { if (event.key === ' ' && day.selectable) (event.preventDefault(), (event.currentTarget as HTMLElement).click()) } }))}
                      class={styles.day}
                      data-calendar-part="day"
                      aria-label={day.name}
                      aria-current={(day.cell.today) ? 'date' : undefined}
                      tabindex={(day.off ? undefined : day.cell.focused ? 0 : -1) as never}
                      data-selected={undefined}
                      data-range-start={(day.start) ? '' : undefined}
                      data-range-middle={(day.middle) ? '' : undefined}
                      data-range-end={(day.end) ? '' : undefined}
                      data-today={(day.cell.today) ? '' : undefined}
                      data-unavailable={(day.unavailable) ? '' : undefined}
                      data-disabled={(day.off) ? '' : undefined}
                      >{day.date.day
                    }</div
                  ></td
                >{/if
              }{/each
            }</tr
          >{/each
        }</tbody
      ></table
    >{/key
  }</div
>{/if
}{@render joined.end?.()}
